// ActivityEntry defines model for ActivityEntry.
type ActivityEntry struct {
	Action string `json:"action"`
	Actor  *struct {
		Id   int64  `json:"id"`
		Name string `json:"name"`
	} `json:"actor"`

	// ByStaff True when staff did this while acting as the actor.
	ByStaff   bool                   `json:"by_staff"`
	Changes   map[string]interface{} `json:"changes"`
	CreatedAt time.Time              `json:"created_at"`
	Id        int64                  `json:"id"`

	// Impersonator Who acted as the actor. Null unless the reader holds `activity.view.all`.
	Impersonator *struct {
		// Id 0 when that account was deleted.
		Id   int64  `json:"id"`
		Name string `json:"name"`
	} `json:"impersonator"`
	Ip          *string `json:"ip"`
	RequestId   *string `json:"request_id"`
	SubjectId   *int64  `json:"subject_id"`
	SubjectType string  `json:"subject_type"`

	// TenantId Null for system audit log entries.
	TenantId *int64 `json:"tenant_id"`
}

// ActivityFacetCount defines model for ActivityFacetCount.
type ActivityFacetCount struct {
	Total int64  `json:"total"`
	Value string `json:"value"`
}

// ActivityFacets defines model for ActivityFacets.
type ActivityFacets struct {
	Actions []ActivityFacetCount `json:"actions"`
	Actors  []struct {
		Id    int64  `json:"id"`
		Name  string `json:"name"`
		Total int64  `json:"total"`
	} `json:"actors"`

	// LastDay Entries in the last 24 hours.
	LastDay  int64                `json:"last_day"`
	Subjects []ActivityFacetCount `json:"subjects"`
}

// ActivityFeedEnvelope defines model for ActivityFeedEnvelope.
type ActivityFeedEnvelope struct {
	Data  []ActivityEntry `json:"data"`
	Links struct {
		Next *string `json:"next"`
	} `json:"links"`
	Meta struct {
		NextCursor *string `json:"next_cursor"`
		Path       string  `json:"path"`
		PerPage    int     `json:"per_page"`

		// Total Entries matching the filters, across every page.
		Total int64 `json:"total"`
	} `json:"meta"`
}

